  always @(posedge clk) acc_last <= acc_out;
  hpc2 ufin (.clk(clk), .a(acc_last), .b(acc_out), .r(rnd[224:222]), .c(dec));

  reg [3:0] lastp; always @(posedge clk) lastp <= {lastp[2:0], lp[16]};
  assign dvalid = lastp[3];
